export type WorldState = ReturnType<typeof createInitialWorld>;

export interface WorldProtocol {
  reset(): WorldState;
  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): { success: true; newState: WorldState } | { success: false; error: string };
  getEntityState(state: WorldState, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldState): Record<string, string>;
}

type Operation = (state: WorldState) => WorldState;

const operations: Record<string, Operation> = {
  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceFen1,
  advanceFen2,
  advanceOskFen,
};

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(state, operationDisplayName) {
    const operation = operations[operationDisplayName];
    if (!operation) {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return { success: true, newState: operation(state) };
    } catch (error) {
      return { success: false, error: errorMessage(error) };
    }
  },

  getEntityState(state, entityDisplayName): string {
    switch (entityDisplayName.toLowerCase()) {
      case "osk":
