      case "fen":
        return state.fen;
      case "vok":
        return state.vok;
      case "zef":
        return state.zef;
      case "tal":
        return state.tal;
      default:
        return "";
    }
  },

  toAbstractSnapshot(state): Record<string, string> {
    return {
      osk: state.osk,
      fen: state.fen,
      vok: state.vok,
      zef: state.zef,
      tal: state.tal,
    };
  },
};
